import { setTimeout as wait } from "node:timers/promises";

// fetch has no retry API. Keep policy here, where each attempt can be retained
// and charged as unknown without replaying the surrounding browser loop.
export const providerRetryPolicy = Object.freeze({
  maxAttempts: 3,
  backoffMs: [1000, 2000],
  maxRetryAfterMs: 30000,
  requestTimeoutMs: 120000,
});

function retryDelay(headers, attempt) {
  const value = headers["retry-after"];
  const seconds = value === undefined ? NaN : Number(value);
  const date = Date.parse(value);
  const requested = Number.isFinite(seconds)
    ? seconds * 1000
    : Number.isFinite(date)
      ? date - Date.now()
      : 0;
  return Math.max(
    providerRetryPolicy.backoffMs[attempt - 1],
    Math.min(providerRetryPolicy.maxRetryAfterMs, Math.max(0, requested)),
  );
}

function check(signal, deadline) {
  if (signal?.aborted) throw new Error("Operator Stop");
  if (Date.now() >= deadline) throw new Error("Time limit");
}

/** Share one attempt budget for HTTP failures and caller-selected response recovery. */
export async function requestProvider({
  api,
  apiKey,
  request,
  requestAI,
  managedCore,
  signal,
  deadline,
  remainingAttempts = providerRetryPolicy.maxAttempts,
  headersFor,
  record,
  retryResponseReason,
}) {
  const serialized = JSON.stringify(request);
  const maxAttempts = Math.min(
    providerRetryPolicy.maxAttempts,
    remainingAttempts,
  );
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    check(signal, deadline);
    const started = Date.now();
    const row = { attempt, at: new Date(started).toISOString() };
    const timeout = AbortSignal.timeout(
      Math.max(
        1,
        Math.min(providerRetryPolicy.requestTimeoutMs, deadline - started),
      ),
    );
    const requestSignal = signal ? AbortSignal.any([timeout, signal]) : timeout;
    let response, bodyText, body;
    try {
      // Preserve the selected host transport; failures never switch routes.
      // A fresh copy keeps a host adapter from mutating a later attempt's input.
      response = requestAI
        ? await requestAI(JSON.parse(serialized), requestSignal)
        : await fetch(api, {
            method: "POST",
            redirect: "error",
            headers: {
              Authorization: `Bearer ${apiKey}`,
              "Content-Type": "application/json",
            },
            body: serialized,
            signal: requestSignal,
          });
      row.httpStatus = response.status;
      row.headers = headersFor(response);
      bodyText = await response.text();
      try {
        body = JSON.parse(bodyText);
      } catch {
        // Non-JSON errors (for example a proxy 502 page) are still HTTP errors.
        if (response.ok) throw new Error("Provider returned invalid JSON");
      }
    } catch (error) {
      row.durationMs = Date.now() - started;
      row.error = String(error);
      await record({ row, bodyText, body });
      check(signal, deadline);
      throw error;
    }
    row.durationMs = Date.now() - started;
    const managedNonRetryable =
      managedCore === true &&
      requestAI &&
      response.status === 429 &&
      body?.statusCode === 429 &&
      body.code === "ai_gateway_rejected" &&
      body.retryable === false;
    const responseRetryReason = response.ok
      ? retryResponseReason?.(body)
      : undefined;
    const retryable =
      !managedNonRetryable &&
      ([408, 409, 429].includes(response.status) ||
        (response.status >= 500 && response.status <= 599) ||
        Boolean(responseRetryReason));
    if (retryable && attempt < maxAttempts)
      row.retry = {
        delayMs: retryDelay(row.headers, attempt),
        status: "waiting",
        ...(responseRetryReason && { reason: responseRetryReason }),
      };
    await record({ row, bodyText, body });
    if (!row.retry) {
      check(signal, deadline);
      return { response, body, row };
    }
    const waitStarted = Date.now();
    try {
      check(signal, deadline);
      // The run deadline also aborts Retry-After and backoff waits.
      const remaining = AbortSignal.timeout(Math.max(1, deadline - Date.now()));
      await wait(row.retry.delayMs, undefined, {
        signal: signal ? AbortSignal.any([remaining, signal]) : remaining,
      });
      check(signal, deadline);
      row.retry.status = "returned";
    } catch (error) {
      row.retry.status = "interrupted";
      row.retry.error = String(error);
      throw error;
    } finally {
      row.retry.actualDelayMs = Date.now() - waitStarted;
      await record({ row, bodyText, body, update: true });
    }
  }
}
